package com.bookeat.wallet.service;
import com.bookeat.wallet.dto.*;import com.bookeat.wallet.entity.*;import com.bookeat.wallet.enums.*;import com.bookeat.wallet.repository.*;import com.bookeat.wallet.mapper.WalletMapper;
import com.bookeat.payment.service.PaymentWalletPort;import com.bookeat.payment.repository.*;import com.bookeat.payment.enums.PaymentStatus;import com.bookeat.order.repository.FoodOrderRepository;import com.bookeat.order.enums.FoodOrderStatus;import com.bookeat.reservation.repository.ReservationRepository;import com.bookeat.reservation.enums.ReservationStatus;import com.bookeat.review.repository.ReviewRepository;import com.bookeat.review.enums.ReviewStatus;
import com.bookeat.commerce.service.*;import com.bookeat.common.audit.AuditService;import com.bookeat.common.response.PageResponse;import com.bookeat.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.data.domain.*;import java.util.*;import java.time.*;import java.math.BigDecimal;
@Service @RequiredArgsConstructor @Transactional public class WalletServiceImpl implements WalletService,PaymentWalletPort,com.bookeat.payment.service.RefundObserver {
 private final WalletRepository wallets;private final WalletTransactionRepository entries;private final RewardRuleRepository rewardRules;private final WalletMapper mapper;private final CommerceAccess access;private final IdempotencyService idempotency;private final JdbcTemplate jdbc;private final AuditService audit;private final Clock clock;private final PaymentRepository payments;private final PaymentLineRepository lines;private final FoodOrderRepository orders;private final ReservationRepository reservations;private final ReviewRepository reviews;
 public Wallet lock(UUID customer){var found=jdbc.query("select id from customers where id=? for update",(r,n)->r.getObject(1,UUID.class),customer);if(found.isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("insert into wallets(id,customer_id,balance,reward_points) values(?,?,0,0) on conflict(customer_id) do nothing",UUID.randomUUID(),customer);return wallets.findByCustomerId(customer).orElseThrow();}
 public WalletResponses.Balance balance(UUID actor){return mapper.balance(lock(access.customer(actor)));}
 public PageResponse<WalletResponses.Entry> history(UUID actor,int page,int size){var w=lock(access.customer(actor));return PageResponse.from(entries.findByWalletId(w.getId(),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(mapper::entry));}
 @Transactional(readOnly=true) public List<WalletResponses.Rule> rules(){return active().stream().map(mapper::rule).toList();}
 private List<RewardRule> active(){return rewardRules.findAll().stream().filter(r->r.isActive()&&!clock.instant().isBefore(r.getEffectiveFrom())&&(r.getEffectiveUntil()==null||clock.instant().isBefore(r.getEffectiveUntil()))).sorted(Comparator.comparing(RewardRule::getEffectiveFrom).reversed().thenComparing(RewardRule::getId)).toList();}
 private RewardRule rule(RewardRuleType type){return active().stream().filter(r->r.getRuleType()==type).findFirst().orElseThrow(()->new ApiException(ErrorCode.REWARD_UNAVAILABLE));}
 public WalletResponses.Redemption calculate(UUID actor,long points){var w=lock(access.customer(actor));var r=rule(RewardRuleType.REDEMPTION);try{return new WalletResponses.Redemption(points,WalletRules.redeem(w.getRewardPoints(),points,r.getConversionValue()),"INR",r.getId());}catch(IllegalArgumentException|ArithmeticException ex){throw new ApiException(ErrorCode.INSUFFICIENT_BALANCE);}}
 public WalletResponses.Balance redeem(UUID actor,String key,WalletRequests.Redemption q){UUID c=access.customer(actor);idempotency.execute(actor,"reward-redeem",key,q,()->{var w=lock(c);var rule=rule(RewardRuleType.REDEMPTION);BigDecimal value;try{value=WalletRules.redeem(w.getRewardPoints(),q.points(),rule.getConversionValue());}catch(IllegalArgumentException ex){throw new ApiException(ErrorCode.INSUFFICIENT_BALANCE);}var entry=entry(w,WalletTransactionType.REWARD_REDEEMED,"REDEMPTION",UUID.randomUUID(),value,-q.points(),actor,"Points converted using server rule "+rule.getId());return entry.getId();});return mapper.balance(lock(c));}
 public WalletResponses.Balance adjust(UUID actor,UUID customer,String key,WalletRequests.Adjustment q){idempotency.execute(actor,"wallet-adjust",key,Map.of("customer",customer,"request",q),()->{if(q.amount().signum()==0&&q.points()==0)throw new ApiException(ErrorCode.VALIDATION_FAILED);return entry(lock(customer),WalletTransactionType.ADMIN_ADJUSTMENT,"ADMIN_ADJUSTMENT",UUID.randomUUID(),q.amount(),q.points(),actor,q.reason()).getId();});return mapper.balance(lock(customer));}
 public WalletResponses.Balance claim(UUID actor,String key,WalletRequests.Claim q){UUID c=access.customer(actor);idempotency.execute(actor,"reward-claim",key,q,()->{if(q.ruleType()==RewardRuleType.SPEND){var rid=payments.restaurantId(q.referenceId()).orElseThrow(()->new ApiException(ErrorCode.REWARD_UNAVAILABLE));access.lock(rid);if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from refunds where payment_id=? and status not in ('REJECTED','FAILED'))",Boolean.class,q.referenceId())))throw new ApiException(ErrorCode.REWARD_UNAVAILABLE);}var w=lock(c);var rule=rule(q.ruleType());UUID reference=q.referenceId();switch(q.ruleType()){
 case SPEND->{var p=payments.findById(reference).filter(x->x.getCustomerId().equals(c)&&x.getStatus()==PaymentStatus.SUCCESS&&x.getGateway()!=com.bookeat.payment.enums.PaymentGateway.WALLET).orElseThrow(()->new ApiException(ErrorCode.REWARD_UNAVAILABLE));if(p.getAmount().compareTo(rule.getMinimumSpend())<0||lines.findByPaymentId(p.getId()).stream().anyMatch(l->orders.findById(l.getFoodOrderId()).orElseThrow().getStatus()!=FoodOrderStatus.COMPLETED))throw new ApiException(ErrorCode.REWARD_UNAVAILABLE);}
 case FIRST_BOOKING->{var r=reservations.findByIdAndCustomerId(reference,c).filter(x->x.getStatus()==ReservationStatus.COMPLETED).orElseThrow(()->new ApiException(ErrorCode.REWARD_UNAVAILABLE));reference=c;}
 case REVIEW->{reviews.findById(reference).filter(x->x.getCustomerId().equals(c)&&x.getStatus()==ReviewStatus.VISIBLE).orElseThrow(()->new ApiException(ErrorCode.REWARD_UNAVAILABLE));}
 default->throw new ApiException(ErrorCode.REWARD_UNAVAILABLE);}
 int inserted=jdbc.update("insert into reward_claims(customer_id,rule_type,reference_id) values(?,?,?) on conflict do nothing",c,q.ruleType().name(),reference);if(inserted==0)return w.getId();return entry(w,WalletTransactionType.REWARD_EARNED,q.ruleType().name(),reference,BigDecimal.ZERO,rule.getPoints(),actor,"Verified reward rule "+rule.getId()).getId();});return mapper.balance(lock(c));}
 public void debit(UUID customer,UUID payment,BigDecimal amount,UUID actor){entry(lock(customer),WalletTransactionType.DEBIT,"PAYMENT",payment,amount.negate(),0,actor,"Wallet payment");}
 public void refund(UUID customer,UUID refund,BigDecimal amount,UUID actor){entry(lock(customer),WalletTransactionType.REFUND,"REFUND",refund,amount,0,actor,"Approved wallet refund");}
 private WalletTransaction entry(Wallet w,WalletTransactionType type,String referenceType,UUID reference,BigDecimal amount,long points,UUID actor,String reason){var existing=jdbc.query("select id from wallet_transactions where wallet_id=? and transaction_type=? and reference_type=? and reference_id=?",(r,n)->r.getObject(1,UUID.class),w.getId(),type.name(),referenceType,reference);if(!existing.isEmpty())return entries.findById(existing.get(0)).orElseThrow();BigDecimal after;long pointsAfter;long debtBefore=w.getRewardDebt(),debtAfter=debtBefore;try{after=WalletRules.balance(w.getBalance(),amount);var pointState=WalletRules.adjustPoints(w.getRewardPoints(),debtBefore,points,type==WalletTransactionType.REWARD_REVERSED);pointsAfter=pointState.points();debtAfter=pointState.debt();}catch(IllegalArgumentException|ArithmeticException e){throw new ApiException(ErrorCode.INSUFFICIENT_BALANCE);}var t=new WalletTransaction();t.setWalletId(w.getId());t.setTransactionType(type);t.setReferenceType(referenceType);t.setReferenceId(reference);t.setAmount(amount);t.setPoints(points);t.setBalanceBefore(w.getBalance());t.setBalanceAfter(after);t.setPointsBefore(w.getRewardPoints());t.setPointsAfter(pointsAfter);t.setDebtBefore(debtBefore);t.setDebtAfter(debtAfter);t.setActorId(actor);t.setReason(reason);w.setRewardDebt(debtAfter);w.setBalance(after);w.setRewardPoints(pointsAfter);entries.saveAndFlush(t);audit.record(actor,type==WalletTransactionType.REWARD_EARNED?"REWARD_POINTS_EARNED":"WALLET_"+type,"WalletTransaction",t.getId(),null);wallets.flush();return t;}
 public WalletResponses.Rule createRule(UUID actor,WalletRequests.Rule q){if(q.effectiveUntil()!=null&&!q.effectiveUntil().isAfter(q.effectiveFrom())||q.ruleType()==RewardRuleType.REDEMPTION&&q.conversionValue().signum()<=0)throw new ApiException(ErrorCode.VALIDATION_FAILED);var r=new RewardRule();r.setRuleType(q.ruleType());r.setMinimumSpend(q.minimumSpend());r.setPoints(q.points());r.setConversionValue(q.conversionValue());r.setActive(q.active());r.setEffectiveFrom(q.effectiveFrom());r.setEffectiveUntil(q.effectiveUntil());rewardRules.saveAndFlush(r);audit.record(actor,"REWARD_RULE_CREATED","RewardRule",r.getId(),null);return mapper.rule(r);}
 public WalletResponses.Rule disableRule(UUID actor,UUID id,long version){var r=rewardRules.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(r.getVersion(),version);r.setActive(false);rewardRules.flush();audit.record(actor,"REWARD_RULE_DISABLED","RewardRule",id,null);return mapper.rule(r);}
 public void completed(com.bookeat.payment.entity.Payment p,com.bookeat.payment.entity.Refund refund,UUID actor){var w=lock(p.getCustomerId());Long granted=jdbc.queryForObject("select coalesce(sum(points),0) from wallet_transactions where wallet_id=? and transaction_type='REWARD_EARNED' and reference_type='SPEND' and reference_id=?",Long.class,w.getId(),p.getId());long target=BigDecimal.valueOf(granted).multiply(p.getRefundedAmount()).divide(p.getAmount(),0,java.math.RoundingMode.DOWN).longValueExact();Long reversed=jdbc.queryForObject("select coalesce(sum(points),0) from reward_refund_reversals where payment_id=?",Long.class,p.getId());long delta=Math.max(0,target-reversed);int n=jdbc.update("insert into reward_refund_reversals(refund_id,payment_id,points) values(?,?,?) on conflict do nothing",refund.getId(),p.getId(),delta);if(n==1&&delta>0)entry(w,WalletTransactionType.REWARD_REVERSED,"REFUND_REWARD",refund.getId(),BigDecimal.ZERO,-delta,actor,"Proportional spend reward reversal; any shortfall is future reward debt");}
}
